html:
{%- from "iso_compliance/templates/includes/controlled_document_macros.html" import
	control_header, watermark, authority_block, change_history, body with context -%}

<style>
	.print-format { font-family: "Helvetica Neue", Arial, sans-serif; font-size: 9.5pt; color: #111; }

	/* ---- controlled header, repeated on every page ---- */
	table.cd-header { width: 100%; border-collapse: collapse; table-layout: fixed; }
	table.cd-header td, table.cd-header th {
		border: 0.6pt solid #000; padding: 2.4pt 4pt; font-size: 7.6pt; vertical-align: middle;
	}
	.cd-lbl { text-transform: uppercase; letter-spacing: 0.2pt; font-size: 5.6pt;
		color: #555; font-weight: 600; line-height: 1.1; margin-bottom: 1pt; }
	.cd-val { font-size: 8pt; font-weight: 700; line-height: 1.15; }
	.cd-org { width: 22%; }
	.cd-org-name { font-weight: 700; font-size: 8.6pt; letter-spacing: 0.2pt; line-height: 1.15; }
	.cd-org-addr { font-size: 5.8pt; color: #444; line-height: 1.15; }
	.cd-strong { font-weight: 700; }
	.cd-nowrap { white-space: nowrap; }
	.cd-c-num { width: 21%; }
	.cd-c-title { width: 23%; }
	.cd-c-ctl { width: 13%; }
	.cd-c-st { width: 9%; }
	.cd-c-num .cd-val { font-size: 7.2pt; }
	.cd-c-ctl .cd-val, .cd-c-st .cd-val { font-size: 7.2pt; }
	.cd-sub { display: block; font-weight: 400; font-size: 6pt; color: #555; margin-top: 1pt; }

	/* ---- footer ---- */
	table.cd-footer { width: 100%; border-top: 0.6pt solid #000; border-collapse: collapse;
		padding-top: 3pt; font-size: 6.4pt; color: #333; line-height: 1.3; }
	table.cd-footer td { padding: 3pt 2pt 0; vertical-align: top; }
	.cd-notice { text-transform: uppercase; letter-spacing: 0.2pt; }
	.cd-pageno { width: 30%; text-align: right; white-space: nowrap; font-weight: 700;
		font-size: 6.6pt; color: #111; }

	/* ---- body ---- */
	.cd-section { margin: 0 0 11pt; }
	.cd-h2 { font-size: 10.5pt; font-weight: 700; margin: 0 0 4pt;
		border-bottom: 0.8pt solid #333; padding-bottom: 2pt; }
	.cd-h3 { font-size: 9.5pt; font-weight: 700; margin: 7pt 0 2pt; }
	.cd-rich { line-height: 1.45; text-align: justify; }
	.cd-rich p { margin: 0 0 5pt; }
	.cd-list { margin: 0; padding-left: 16pt; line-height: 1.45; }
	.cd-step { margin-bottom: 6pt; }

	table.cd-table { width: 100%; border-collapse: collapse; margin-top: 3pt; }
	table.cd-table td, table.cd-table th { border: 0.5pt solid #666; padding: 3pt 4.5pt;
		font-size: 8.2pt; vertical-align: top; text-align: left; }
	table.cd-table th { background: #f2f2f2; font-weight: 600; }
	table.cd-history td, table.cd-history th { font-size: 7pt; padding: 2.5pt 3pt; }
	.cd-history .cd-desc { width: 24%; }
	.cd-empty { color: #777; font-style: italic; }

	/* ---- authority ---- */
	table.cd-authority { width: 100%; border-collapse: collapse; margin-top: 14pt; }
	table.cd-authority td, table.cd-authority th { border: 0.6pt solid #000; padding: 5pt 6pt;
		font-size: 8pt; text-align: center; width: 33.33%; }
	table.cd-authority th { background: #ececec; text-transform: uppercase; font-size: 6.8pt;
		letter-spacing: 0.3pt; }
	.cd-sig-name { font-weight: 700; min-height: 22pt; padding-top: 12pt; }
	.cd-sig-date { font-size: 6.6pt; color: #555; }
	.cd-authority-note { font-size: 6.4pt; color: #666; margin-top: 3pt; font-style: italic; }

	/* ---- watermark ---- */
	.cd-watermark { position: fixed; top: 44%; left: 0; width: 100%; text-align: center;
		transform: rotate(-24deg); font-weight: 800; letter-spacing: 3pt;
		pointer-events: none; z-index: 0; text-transform: uppercase; }
	.cd-watermark-draft { font-size: 64pt; color: #c02828; opacity: 0.08; }
	.cd-watermark-obsolete { font-size: 56pt; color: #777777; opacity: 0.10; }
	.cd-watermark-uncontrolled { font-size: 22pt; color: #3c5aa0; opacity: 0.07; }

	.cd-attach { border: 0.8pt dashed #888; padding: 12pt; text-align: center; }
	.cd-attach-label { font-size: 8pt; color: #555; }
	.cd-attach-file { font-weight: 700; margin-top: 4pt; }

	.cd-page-break { page-break-before: always; }
	.cd-body { position: relative; z-index: 1; }
</style>

<div id="header-html">
	{{ control_header(doc) }}
</div>

<div id="footer-html">
	<table class="cd-footer">
		<tr>
			<td class="cd-notice">
				Notice: this document is proprietary and its contents are the exclusive property of
				Hatim Carbon Co. Pvt. Ltd. It may not be reproduced in any form without prior
				written permission.
			</td>
			<td class="cd-pageno">
				{{ doc.name }} &nbsp;&middot;&nbsp; Issue {{ doc.issue_number or "-" }} / Rev {{ doc.revision_number or "-" }}
			</td>
		</tr>
	</table>
</div>

{{ watermark(doc) }}

<div class="cd-body">
	{{ body(doc) }}
	{{ authority_block(doc) }}
	{{ change_history(doc) }}
</div>
